CREATE TABLE IF NOT EXISTS consumer_inbox(consumer_name varchar(64) NOT NULL,event_id varchar(128) NOT NULL,payload_hash char(64) NOT NULL,processed_at datetime(6) NOT NULL,PRIMARY KEY(consumer_name,event_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS consumer_receipt(consumer_name varchar(64) NOT NULL,operation_key char(64) NOT NULL,payload_hash char(64) NOT NULL,responses json NOT NULL,PRIMARY KEY(consumer_name,operation_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS retry_job(event_id varchar(128) PRIMARY KEY,aggregate_id varchar(128) NOT NULL,aggregate_version bigint NOT NULL,event_type varchar(64) NOT NULL,payload json NOT NULL,payload_hash char(64) NOT NULL,state varchar(16) NOT NULL,attempt int NOT NULL DEFAULT 0,lease_token varchar(128),lease_until datetime(6),next_attempt_at datetime(6) NOT NULL,created_at datetime(6) NOT NULL,published_at datetime(6),consumer_name varchar(64) NOT NULL,failure_count int NOT NULL,INDEX pending(state,next_attempt_at,event_id),INDEX expired(state,lease_until,event_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS recovery_case(case_id varchar(128) PRIMARY KEY,aggregate_type varchar(64) NOT NULL,aggregate_id varchar(128) NOT NULL,business_state varchar(64) NOT NULL,recovery_status varchar(32) NOT NULL,object_version bigint NOT NULL,active_key char(64),evidence longtext NOT NULL,operator_id varchar(128),resolution_reason varchar(1024),created_at datetime(6) NOT NULL,closed_at datetime(6),UNIQUE KEY active_case(active_key),INDEX object_cases(aggregate_type,aggregate_id,closed_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS deferred_fact(consumer_name varchar(64) NOT NULL,event_id varchar(128) NOT NULL,aggregate_type varchar(64) NOT NULL,aggregate_id varchar(128) NOT NULL,payload json NOT NULL,payload_hash char(64) NOT NULL,replayed_event_id varchar(128),created_at datetime(6) NOT NULL,PRIMARY KEY(consumer_name,event_id),INDEX pending_facts(aggregate_type,aggregate_id,replayed_event_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS message_quarantine(consumer_name varchar(64) NOT NULL,body_hash char(64) NOT NULL,body longblob NOT NULL,reason varchar(1024) NOT NULL,created_at datetime(6) NOT NULL,PRIMARY KEY(consumer_name,body_hash)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
